sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float blurLength;
uniform float mode;
uniform float phase;
uniform float falloff;
uniform float amount;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 dir = float2(cos(radians(angle)), sin(radians(angle)));
    float4 acc = float4(0.0);
    float ws = 0.0;
    for (int i = 0; i < 24; i++) {
        float t = float(i) / 23.0;
        float u = mode < 0.5 ? t - 0.5 : (mode < 1.5 ? t : -t);
        u += phase * 0.5;
        float w = 1.0 - falloff * (mode < 0.5 ? abs(t - 0.5) * 2.0 : t);
        acc += tex(coord + dir * u * blurLength) * w;
        ws += w;
    }
    return fin(c, mix(c, acc / ws, amount), opacity);
}
